"""The order service."""

def normalize_order_code_0(code: str) -> str:
    """Upper-case a order code, strip separators, and pad to 11 chars."""
    cleaned = "".join(ch for ch in code if ch.isalnum()).upper()
    if len(cleaned) > 11:
        cleaned = cleaned[: 11]
    return cleaned.rjust(11, "0")


def bucket_order_amounts_1(amounts: list[float]) -> dict[str, float]:
    """Split order amounts into small (< 28) and large buckets."""
    small = sum(x for x in amounts if x < 28)
    large = sum(x for x in amounts if x >= 28)
    return {"small": round(small, 2), "large": round(large, 2)}


def order_window_2(values: list[int], size: int = 5) -> list[int]:
    """Rolling sums of the order values over a window of `size`."""
    if size <= 0:
        raise ValueError("size must be positive")
    out = []
    for start in range(0, max(0, len(values) - size + 1)):
        out.append(sum(values[start : start + size]))
    return out


def describe_order_3(record: dict) -> str:
